fn is_palindrome(values: &[i32]) -> bool {
    match values {
        [] | [_] => true,
        [first, middle @ .., last] => first == last && is_palindrome(middle),
    }
}

fn shape_of(values: &[i32]) -> String {
    match values {
        [] => "empty".to_string(),
        [one] => format!("single {one}"),
        [a, b] => format!("pair {a} {b}"),
        v if is_palindrome(v) => "palindrome".to_string(),
        [first, .., last] => format!("{} items from {first} to {last}", values.len()),
    }
}

fn age_group(age: u32) -> String {
    match age {
        n @ 0..=12 => format!("child {n}"),
        n @ 13..=19 => format!("teen {n}"),
        20..=64 => "adult".to_string(),
        n => format!("senior {n}"),
    }
}

fn parse_move(text: &str) -> Option<(char, u32)> {
    let cleaned: String = text.chars().filter(|c| !c.is_whitespace()).collect();
    let mut chars = cleaned.chars();
    let Some(dir @ ('N' | 'E' | 'S' | 'W')) = chars.next().map(|c| c.to_ascii_uppercase()) else {
        return None;
    };
    let Ok(distance) = chars.as_str().parse::<u32>() else {
        return None;
    };
    if distance == 0 {
        return None;
    }
    Some((dir, distance))
}

fn quadrant(point: (i32, i32)) -> &'static str {
    match point {
        (0, 0) => "origin",
        (_, 0) => "x axis",
        (0, _) => "y axis",
        (x, y) if x > 0 && y > 0 => "I",
        (x, y) if x < 0 && y > 0 => "II",
        (x, y) if x < 0 && y < 0 => "III",
        _ => "IV",
    }
}

unitTests:
test("shapes of slices", || {
    check_eq(shape_of(&[]), "empty");
    check_eq(shape_of(&[7]), "single 7");
    check_eq(shape_of(&[1, 2]), "pair 1 2");
    check_eq(shape_of(&[1, 2, 3, 2, 1]), "palindrome");
    check_eq(shape_of(&[4, 4, 4]), "palindrome");
    check_eq(shape_of(&[1, 2, 3, 4]), "4 items from 1 to 4");
});

test("age groups", || {
    check_eq(age_group(0), "child 0");
    check_eq(age_group(12), "child 12");
    check_eq(age_group(13), "teen 13");
    check_eq(age_group(40), "adult");
    check_eq(age_group(65), "senior 65");
});

test("parsing moves", || {
    check_eq(parse_move("N12"), Some(('N', 12)));
    check_eq(parse_move("e3"), Some(('E', 3)));
    check_eq(parse_move(" S 4 "), Some(('S', 4)));
    check_eq(parse_move("X5"), None);
    check_eq(parse_move("N"), None);
    check_eq(parse_move("W0"), None);
    check_eq(parse_move("N-3"), None);
    check_eq(parse_move(""), None);
});

test("quadrants", || {
    check_eq(quadrant((0, 0)), "origin");
    check_eq(quadrant((5, 0)), "x axis");
    check_eq(quadrant((0, -2)), "y axis");
    check_eq(quadrant((3, 4)), "I");
    check_eq(quadrant((-3, 4)), "II");
    check_eq(quadrant((-3, -4)), "III");
    check_eq(quadrant((3, -4)), "IV");
});

